```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' GROUP BY 1,2,3",
          "claim": "In the incident, RoutePlanController.getCheapestRoutes and getQuickestRoutes take about 1.86 s p50 internally, while getMinStopStations stays near 20 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind k, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3,4",
          "claim": "cheapestRoute and quickestRoute server spans rose from about 41 ms p50 to about 1,857 ms p50; minStopStations is unchanged at about 20 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, attr_span_kind k, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms, avg(CASE WHEN attr_status_code='STATUS_CODE_ERROR' THEN 1 ELSE 0 END) err FROM abnormal_traces WHERE service_name='ts-route-plan-service' GROUP BY 1,2,3",
          "claim": "Route-plan Client calls to downstream dependencies stay at about 7–21 ms p50, so the delay is in-process, not on the wire."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, avg(value) v, max(value) mx FROM abnormal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('container.cpu.usage','container.memory.working_set','container.filesystem.usage') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value), max(value) FROM normal_metrics WHERE service_name='ts-route-plan-service' AND metric IN ('container.cpu.usage','container.memory.working_set','container.filesystem.usage') GROUP BY 1,2",
          "claim": "Container CPU, memory and filesystem usage stay near normal levels, so the slowdown is not explained by container resource exhaustion."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3 ORDER BY 1,2",
          "claim": "Travel-plan cheapest and quickest server spans and its Client calls rise to about 1.86 s p95, matching route-plan's slowdown."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' AND span_name LIKE '%plan%' GROUP BY 1,2,3 ORDER BY 1,2",
          "claim": "ts-ui-dashboard's travelPlan cheapest and quickest server spans show about 1.87 s p95, inherited from travel-plan."
        }
      ]
    }
  ]
}
```

